WITH with_gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) > INTERVAL 7 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM sessions), sessionized AS (SELECT id, customer_id, started_at, country, SUM(new_group_flag) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT CASE WHEN session_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_id_tier, country, MAX(started_at) AS ended_at, COUNT_IF(country = 'JP') AS jp_events, SORT_ARRAY(COLLECT_SET(country)) AS country_list, APPROX_PERCENTILE(session_id, ARRAY(0.25, 0.5, 0.75)) AS session_id_quartiles FROM sessionized GROUP BY CASE WHEN session_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END, country HAVING COUNT_IF(country = 'JP') >= 1
